import{_ as r,o as a,c as e,aj as o}from"./chunks/framework.Cn87zHeG.js";const d="/onerobot-H1/images/getting-started/first-use/power-switches.png",l="/onerobot-H1/images/getting-started/first-use/controller-layout.png",n="/onerobot-H1/images/faq/ctrl2.webp",u=JSON.parse('{"title":"H1 开箱与首次使用","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"getting-started/first-use.md","filePath":"getting-started/first-use.md"}'),i={name:"getting-started/first-use.md"};function s(h,t,c,g,p,f){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="h1-开箱与首次使用" tabindex="-1">H1 开箱与首次使用 <a class="header-anchor" href="#h1-开箱与首次使用" aria-label="Permalink to &quot;H1 开箱与首次使用&quot;">​</a></h1><p>首次收到机器人时，按 <strong>开箱检查 → 开机前准备 → 开机 → 手柄操作 → 关机</strong> 的顺序完成基础使用。本文适用于 H1 标准版和智能版，配件及选配功能以收到的实物为准。</p><table tabindex="0"><thead><tr><th>要做什么</th><th>说明位置</th></tr></thead><tbody><tr><td>检查机器人与配件</td><td><a href="#unboxing">开箱检查</a>、<a href="#preflight">开机前准备</a></td></tr><tr><td>找到电源开关、查看灯效</td><td><a href="#power-on">开机</a>、<a href="#indicators">状态指示灯</a></td></tr><tr><td>连接手柄、查询按键功能</td><td><a href="#controller">手柄准备</a>、<a href="#controller-buttons">按键功能</a></td></tr><tr><td>结束使用或处理紧急情况</td><td><a href="#power-off">正常关机</a>、<a href="#emergency-stop">紧急停止</a></td></tr><tr><td>联网、调试与开发</td><td><a href="#next">下一步</a></td></tr></tbody></table><h2 id="unboxing" tabindex="-1">开箱检查 <a class="header-anchor" href="#unboxing" aria-label="Permalink to &quot;开箱检查 {#unboxing}&quot;">​</a></h2><ol><li><strong>清点物品。</strong> 按随箱装箱单核对机器人、手柄及其他配件，检查包装、外壳、机械臂、已配置的末端执行器和线缆有无损伤。</li><li><strong>协作搬运。</strong> 整机重量约 <strong>77 kg</strong>，由足够人员配合搬运。禁止拖拽机械臂、头部、线缆或传感器。</li><li><strong>检查安装状态。</strong> 确认机器人、已配置的支架及工作站放置稳定，底盘、紧固件没有松动、变形或运输移位。</li></ol><p>发现松动、破损、漏液、异味或异常发热时，停止使用并联系技术支持。</p><h2 id="preflight" tabindex="-1">开机前准备 <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;开机前准备 {#preflight}&quot;">​</a></h2><p>首次上电应由接受过培训的人员完成。每次使用前，逐项确认以下内容。</p><table tabindex="0"><thead><tr><th>检查项</th><th>需要确认的内容</th></tr></thead><tbody><tr><td>工作区</td><td>运动范围已清空，隔离和监护措施已就绪，操作员站在安全位置</td></tr><tr><td>机器人外观</td><td>双臂、头部、升降机构、底盘及已安装夹爪无损伤</td></tr><tr><td>初始姿态</td><td>机械臂及已配置的主臂处于交付要求的初始位置</td></tr><tr><td>电源与线缆</td><td>电池电量满足任务要求，电源及通信连接牢固</td></tr><tr><td>周边空间</td><td>关节、底盘和线缆周围无异物、缠绕或干涉</td></tr><tr><td>急停</td><td>已了解按钮位置、使用方式，急停功能检查正常</td></tr><tr><td>操作人员</td><td>已束起长发，衣物和随身物品远离运动区域，能够集中注意力操作</td></tr></tbody></table><p>如配置主从系统，按交付要求连接网线及控制线缆，锁紧接口。外部算力工作站和遥操作主机按配套说明上电，确认主臂处于初始位置。</p><h2 id="power-on" tabindex="-1">开机 <a class="header-anchor" href="#power-on" aria-label="Permalink to &quot;开机 {#power-on}&quot;">​</a></h2><h3 id="找到电源开关" tabindex="-1">找到电源开关 <a class="header-anchor" href="#找到电源开关" aria-label="Permalink to &quot;找到电源开关&quot;">​</a></h3><p>H1 的机身普通开关、应急开关和遥控开关如下图。<strong>遥控开关是否配置，以收到的实物为准。</strong> 点击图片可查看原图。</p><p><a href="/onerobot-H1/images/getting-started/first-use/power-switches.png"><img src="'+d+'" alt="机身普通开关、选配遥控开关和应急开关的位置及操作方式"></a></p><table tabindex="0"><thead><tr><th>开关</th><th>操作方式</th></tr></thead><tbody><tr><td>机身普通开关</td><td>点按后按键凹入为通电，按键弹起为断电</td></tr><tr><td>遥控开关（选配）</td><td>点按 <strong>ON</strong> 通电，点按 <strong>OFF</strong> 断电</td></tr><tr><td>应急开关（急停）</td><td>顺时针旋转解除急停，直接按下触发急停，可隔着红胶套按下</td></tr></tbody></table><h3 id="上电步骤" tabindex="-1">上电步骤 <a class="header-anchor" href="#上电步骤" aria-label="Permalink to &quot;上电步骤&quot;">​</a></h3><ol><li>完成<a href="#preflight">开机前准备</a>，确认机器人运动范围内无人。</li><li>确认应急开关已解除，并检查机身普通开关。按键处于凹入状态表示通电；若按键弹起，点按至凹入状态。如配有遥控开关，点按 <strong>ON</strong>，让已配置的电源开关均处于通电状态。</li><li>等待机器人完成启动和初始化，再连接手柄或进入网页工具检查状态。</li></ol><div class="warning custom-block"><p class="custom-block-title">初始化期间</p><p>初始化和校准期间，机械臂可能发生运动。人员应远离机械臂可达范围，保持双手离开关节。</p></div><h3 id="indicators" tabindex="-1">状态指示灯 <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;状态指示灯 {#indicators}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>灯效</th><th>含义</th></tr></thead><tbody><tr><td>白灯慢闪</td><td>未联网</td></tr><tr><td>白灯常亮</td><td>正常</td></tr><tr><td>红灯常亮</td><td>故障</td></tr><tr><td>红灯慢闪</td><td>低电</td></tr><tr><td>白灯呼吸</td><td>充电</td></tr></tbody></table><p>白灯慢闪时，可按<a href="./network-ota.html#connect">网络配置与 OTA</a>连接机器人。红灯常亮时，先通过 <a href="./debug-tool.html#status">H1 调试工具</a>检查状态并处理故障，再进行运动操作。</p><h2 id="controller" tabindex="-1">手柄准备 <a class="header-anchor" href="#controller" aria-label="Permalink to &quot;手柄准备 {#controller}&quot;">​</a></h2><h3 id="外观与连接" tabindex="-1">外观与连接 <a class="header-anchor" href="#外观与连接" aria-label="Permalink to &quot;外观与连接&quot;">​</a></h3><p>下图为本说明书中的手柄。<strong>连接机器人前，将手柄背面下方的拨动开关拨到最左侧。</strong> 点击图片可查看开关位置和放大图。</p><p><a href="/onerobot-H1/images/getting-started/first-use/controller-layout.png"><img src="'+l+'" alt="手柄正面、背面及背面拨动开关放大图，连接前拨到最左侧"></a></p><ol><li>机器人完成开机后，将手柄放在机器人附近，核对背面拨动开关位置。</li><li>按 <strong>Play（HOME）</strong> 键打开手柄。</li><li>如需重新配对，按<a href="./../faq/controller.html#q7">手柄配对说明</a>选择所配手柄对应的操作方式。</li></ol><p>手柄右上方为 <strong>Y、B、A、X</strong> 按钮，左下方为十字方向键。中间有 <strong>Start、Back、Fn（TURBO）、Play（HOME）</strong>，顶部有 <strong>LB、LT、RB、RT</strong>，左右各有一个摇杆。</p><details><summary>旧款手柄外观参考</summary><p><img src="'+n+'" alt="旧款手柄外观"></p><p>旧款手柄的重新配对组合键见<a href="./../faq/controller.html#q7">配对说明</a>。</p></details><h3 id="controller-buttons" tabindex="-1">按键功能 <a class="header-anchor" href="#controller-buttons" aria-label="Permalink to &quot;按键功能 {#controller-buttons}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按键</th><th>功能</th></tr></thead><tbody><tr><td>Play（HOME）</td><td>手柄开机</td></tr><tr><td>Start</td><td>进入主臂控制从臂模式 / 重置姿态，主从控制需配套遥操作设备</td></tr><tr><td>Back</td><td>退出当前模式，进入待机状态，配套固件会执行归位、升降及头部校准</td></tr><tr><td>Y / A</td><td>身体上升 / 下降</td></tr><tr><td>按住 LB</td><td>左夹爪张开，松开后恢复夹紧</td></tr><tr><td>按住 RB</td><td>右夹爪张开，松开后恢复夹紧</td></tr><tr><td>按一下 LT / RT</td><td>加速 / 减速</td></tr><tr><td>十字方向键 上 / 下</td><td>底盘前进 / 后退</td></tr><tr><td>十字方向键 左 / 右</td><td>底盘原地逆时针 / 顺时针旋转</td></tr><tr><td>右摇杆</td><td>上、下、左、右控制头部对应转动</td></tr></tbody></table><p><strong>LT / RT 按当前控制对象调节速度，升降和底盘独立调节。</strong> 控制升降时调节升降速度，控制底盘时调节底盘速度。</p><h3 id="controller-safety" tabindex="-1">首次操作与注意事项 <a class="header-anchor" href="#controller-safety" aria-label="Permalink to &quot;首次操作与注意事项 {#controller-safety}&quot;">​</a></h3><ol><li>确认运动范围内无人、无障碍物，先以低速、空载方式熟悉控制。移动底盘、升降或转动头部前，检查对应运动范围。</li><li>一次完成一个操作，等待当前动作完成后再切换。避免连续重复按同一按键，禁止使用未知功能的按键。</li><li><strong>Start / Back 会触发姿态调整、归位或校准</strong>，具体动作取决于配套固件和设备配置。操作前清空机械臂、升降及头部的运动范围，出现危险时使用<a href="#emergency-stop">本体物理急停</a>。</li><li>操作夹爪时保持手和物品远离夹持区域，注意 <strong>LB / RB 松开后夹爪会恢复夹紧</strong>。</li><li>如使用主从遥操作系统，主臂、从臂、手柄和笔记本按交付配套使用。先低速分别检查左臂、右臂和夹爪，再进行双臂操作。映射方向或零位不确定时，退出遥操作并检查。</li></ol><p>手柄没有反应或无法配对时，见<a href="./../faq/controller.html#q11">手柄遥操作常见问题</a>。</p><h2 id="power-off" tabindex="-1">正常关机 <a class="header-anchor" href="#power-off" aria-label="Permalink to &quot;正常关机 {#power-off}&quot;">​</a></h2><ol><li>结束当前任务，将双臂和负载置于安全状态，退出控制或遥操作模式，确认机器人停止运动。</li><li>保存需要保留的数据，按配套说明关闭已配置的外部工作站和遥操作设备。</li><li>点按机身普通开关，使按键弹起断电。如使用配套遥控开关，点按 <strong>OFF</strong> 断电。</li></ol><p>日常关机按上述顺序完成。避免拔掉电源或反复按压电源键，强制断电可能造成机械臂下落、硬件损坏或数据丢失。固件升级期间应保持供电稳定。</p><h2 id="emergency-stop" tabindex="-1">紧急停止 <a class="header-anchor" href="#emergency-stop" aria-label="Permalink to &quot;紧急停止 {#emergency-stop}&quot;">​</a></h2><ol><li>出现失控、碰撞、夹挤、异常高速运动或人员进入危险区域时，<strong>立即按下本体应急开关（急停）</strong>，可隔着红胶套按下。</li><li>保持人员远离设备，等待所有运动停止。失能后机械臂可能受重力影响下落，必要时由受训人员固定机械臂和负载。</li><li>查明原因并完成设备检查，确认运动范围内安全后，顺时针旋转解除急停。解除急停时机器人可能恢复供电，应按<a href="#power-on">开机步骤</a>核对各开关的当前状态，等待启动和初始化完成后再操作。</li></ol><h2 id="next" tabindex="-1">下一步 <a class="header-anchor" href="#next" aria-label="Permalink to &quot;下一步 {#next}&quot;">​</a></h2><ul><li><a href="./network-ota.html">网络配置与 OTA</a> — 连接机器人、配置 WiFi、查看固件版本及升级。</li><li><a href="./debug-tool.html">H1 调试工具</a> — 检查设备状态，使用建图、定位、导航和回充等功能。</li><li><a href="./editions.html">产品版本与开发路径</a> — 按标准版或智能版准备开发环境，选择接口与示例。</li></ul>',41)])])}const m=r(i,[["render",s]]);export{u as __pageData,m as default};
